<?php get_header(); ?><main class="site-main"><div class="site-width"><?php while (have_posts()) : the_post(); ?><article><header class="entry-header"><h1 class="entry-title"><?php the_title(); ?></h1></header><div class="entry-content"><?php $legacy_content = get_the_content(); $knowledge = get_page_by_path(get_post_field('post_name'), OBJECT, 'baza_wiedzy'); if ($knowledge && (strpos($legacy_content, '[et_pb_') !== false || trim(wp_strip_all_tags($legacy_content)) === '')) { krd_ig_render_content($knowledge->post_content); } else { krd_ig_render_content($legacy_content); } ?></div></article><?php endwhile; ?></div></main><?php get_footer();